93	
94	            if (dayCount > _options.Captcha.DayMaxGenTimes)
95	            {
96	                return BaseResult.Fail(ErrCodeEnum.Create_Captcha_300801);
97	            }
98	
99	            var setRet = await _redisClient.StringSetAsync(lastestTimeKey, DateTime.Now.ToUnixTimeStamp().ToString(), TimeSpan.FromSeconds(_options.Captcha.MaxGenInterval));
100	
101	            if (!setRet)
102	            {
103	                return BaseResult.Fail(ErrCodeEnum.Err, "值设置异常");
104	            }
105	
106	            // 如果是登录业务，需要校验手机号是否存在系统中
107	            if (model.VerifyType == VaidateCodeReqType.Login)
108	            {
109	                var checkLoginPhone = await _userService.CheckLoginPhoneAsync(model.Phone);
110	
111	                if (!checkLoginPhone.IsSuccess())
