113	                    return BaseResult.Fail(checkLoginPhone);
114	                }
115	            }
116	
117	            // 如果是校验业务，需要校验核验的供应商是否存在系统中
118	            if (model.VerifyType == VaidateCodeReqType.OrgAuth)
119	            {
120	                if (model.Param.Length < 1 || string.IsNullOrWhiteSpace(model.Param[0]) || string.IsNullOrWhiteSpace(model.Param[0].Trim()))
121	                {
122	                    return BaseResult.Fail(ErrCodeEnum.Send_Mobile_Validate_Code_300901);
123	                }
124	
125	                var supplierInfo = await _orgService.GetSupplierInfoByCertNoAsync(model.Param[0].Trim());
126	
127	                if (supplierInfo == null)
128	                {
129	                    return BaseResult.Fail(ErrCodeEnum.Send_Mobile_Validate_Code_300902);
130	                }
131	            }
132	
133	            if (model.VerifyType == VaidateCodeReqType.ChangePhone)
134	            {
135	                if (model.Param.Length < 3 || string.IsNullOrWhiteSpace(model.Param[0]) || string.IsNullOrWhiteSpace(model.Param[1]) || string.IsNullOrWhiteSpace(model.Param[2]))
136	                {
137	                    return BaseResult.Fail(ErrCodeEnum.ParametersInvalid, "用户名、身份证号、原手机号信息不全");
138	                }
139	                var ret = await _userService.CheckChangePhone(model.Param[0], model.Param[1], model.Param[2]);
140	                if (!ret.IsSuccess())
141	                {
142	                    return BaseResult.Fail(ErrCodeEnum.Check_Change_Phone_232201);
143	                }
144	            }
145	
146	            //生成验证码并发送
147	
148	            var captchaRet = await _captchaService.CreateCaptchaAsync(model.Phone);
149	
150	            if (captchaRet.Item1 != ErrCodeEnum.Success)
151	            {
152	                return BaseResult.Fail(captchaRet.Item1, captchaRet.Item2);
153	            }
154	
155	            var msg = string.Format(_options.Captcha.CaptchaTemplate, captchaRet.Item2);
156	
157	            var sendMsg = await _captchaService.DsmSenVerifyCode(model.Phone, msg);
158	
159	            return sendMsg
160	                ? BaseResult.Success
161	                : BaseResult.Fail(ErrCodeEnum.Send_Mobile_Validate_Code_300903);
162	
